import { describe, it, expect } from 'vitest';
import * as git from 'isomorphic-git';
import { recordEvent, replayEvents, getDatabase, createTestContext } from '@hive/core';
import type { HiveContext } from '@hive/core';

const branch = 'hive-test';
async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}

describe('shared commit reachable from two hive branches (fork/merge gap)', () => {
  it('keeps a node visible under every branch whose history contains its commit', async () => {
    const { ctx, dir } = await bootstrap();
    const fs = ctx.fs as any;

    // Two hive branches. Record an 'add' on hive-A, then FORK hive-B at hive-A's HEAD so
    // the very same add commit (identical change_id) is reachable from BOTH branches --
    // exactly what `git branch hive-team hive-local` or a merge between hive branches
    // produces. Nothing in the module speaks to a commit belonging to more than one branch.
    await git.branch({ fs, dir, ref: 'hive-A' });
    const nodeId = await recordEvent(
      ctx,
      { type: 'add', nodeType: 'decision', content: 'shared history', confidence: 90 },
      'hive-A',
    );
    const oid = await git.resolveRef({ fs, dir, ref: 'hive-A' });
    await git.writeRef({ fs, dir, ref: 'refs/heads/hive-B', value: oid, force: true });

    // Rebuild each branch from the log, as replayAllBranches does for every hive branch.
    // hive-A materialises the node (branch = 'hive-A'). hive-B replays the SAME commit:
    // insertNode duplicates change_id, the PRIMARY KEY error is swallowed (P19), and the
    // watermark still advances -- so the shared node is never attributed to hive-B.
    await replayEvents(ctx, 'hive-A', true);
    await replayEvents(ctx, 'hive-B', true);

    // hive-B genuinely contains that commit, so a hive-B-scoped listing MUST find the node.
    const db = getDatabase(ctx);
    const row = db.prepare('SELECT change_id FROM nodes WHERE branch = ? AND change_id = ?')
      .get('hive-B', nodeId) as { change_id: string } | undefined;

    expect(row?.change_id).toBe(nodeId);
  });
});
